head.script:
scwin.onpageload = function() {
    scwin.popupID = $p.getParameter("popupID");
    scwin.popInfo = $p.getParameter("popInfo");
    $p.log("### log  =====> " + scwin.popupID);
    //$p.log("### log  =====> " + JSON.stringify(scwin.popInfo,null,2));
    if (typeof scwin.popInfo.detail != "undefined") {
        dma_user_info.setJSON(scwin.popInfo.detail);
    }
};
scwin.btn_close_onclick = function() {
    scwin.closePopup(scwin.popupID);
};
scwin.closePopup = function(popId) {
    console.log("scwin.closePopup");
    var parentFunc = null;
    if (typeof scwin.popInfo.isClose == "undefined") scwin.popInfo.isClose = true;
    if (scwin.popInfo.isClose) {
        if (scwin.popInfo.mode == "B") {
            window.close();
        } else {
            $p.closePopup(popId, {
                popupTest: "test!!!!"
            });
        }
    }
    var strParam = "";
    if (scwin.popInfo.userCallBack != null && (scwin.popInfo.userCallBack != $p.id) &&
        scwin.popInfo.userCallBack.length > 0 && (scwin.popInfo.userCallBack.length != scwin.popInfo.frameId.length)) {
        if (scwin.popInfo.mode == "B") { // window.open
            parentFunc = opener.eval(scwin.popInfo.frameId + scwin.popInfo.userCallBack)(strParam);
            parentFunc(strParam);
        } else if (scwin.popInfo.mode == "I") { // iframePopup
            parentFunc = parent.eval(scwin.popInfo.userCallBack)(strParam);
            parentFunc(strParam);
        } else { // wframePopup
            eval(scwin.popInfo.userCallBack)(strParam);
        }
    }
};
scwin.onpageunload = function() {};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
